# Clamp function

def clamp(value, format="{:}", floor=None, ceil=None, floor_token="<", ceil_token=">"):
    """Return the value formatted, clamped between floor and ceil.

    Parameters
    ----------
    value : Any
        The value to format.
    format : str | Callable[[Any], str]
        Format string or callable used to format the value.
    floor, ceil : Any, optional
        Lower and upper bounds. If value is outside these bounds, the bound
        value is formatted and prefixed by ``floor_token`` or ``ceil_token``.
    floor_token, ceil_token : str, optional
        Tokens prepended when the value is clamped.
    """
    if value is None:
        return None
    # Determine formatter
    if callable(format):
        formatter = format
    else:
        def formatter(v):
            return format.format(v)
    # Check bounds
    if floor is not None and value < floor:
        return f"{floor_token}{formatter(floor)}"
    if ceil is not None and value > ceil:
        return f"{ceil_token}{formatter(ceil)}"
    return formatter(value)
